<template><BioNexusDialog ref="dialog" size="standard" :prevent-close="saving" :kicker="mode==='create'?'Nuevo registro':'Editar registro'" :title="mode==='create'?'Crear moneda':'Editar moneda'" @close="reset"><section class="currency-form"><BioNexusFormField label="Moneda" field-id="currency-code" :error="errors.code" help="Selecciona la moneda oficial que identificará los importes." required><select v-if="mode==='create'" id="currency-code" ref="firstInput" v-model="draft.code" class="bio-nexus-field" @change="selectCurrency"><option value="">Seleccione una moneda</option><option v-for="item in options" :key="item.code" :value="item.code">{{item.name}} ({{item.code}})</option></select><input v-else id="currency-code" ref="firstInput" :value="identity" class="bio-nexus-field readonly" readonly></BioNexusFormField><BioNexusFormField label="Nombre" field-id="currency-name" :error="errors.name" required><input id="currency-name" v-model="draft.name" class="bio-nexus-field" maxlength="80" @input="syncDirty"></BioNexusFormField><BioNexusFormField label="Símbolo" field-id="currency-symbol" :error="errors.symbol" help="Ejemplos: Bs. o $." required><input id="currency-symbol" v-model="draft.symbol" class="bio-nexus-field" maxlength="12" @input="syncDirty"></BioNexusFormField><BioNexusFormField label="Posición del símbolo" field-id="currency-position"><select id="currency-position" v-model="draft.symbolPosition" class="bio-nexus-field" @change="syncDirty"><option value="before">Antes del monto</option><option value="after">Después del monto</option></select></BioNexusFormField><BioNexusFormField label="Decimales" field-id="currency-decimals" :error="errors.decimals" help="Cantidad de decimales mostrados, entre 0 y 6."><input id="currency-decimals" v-model.number="draft.decimalPlaces" class="bio-nexus-field" type="number" min="0" max="6" @input="syncDirty"></BioNexusFormField><div class="preview"><span>Vista previa</span><strong>{{preview}}</strong></div><div v-if="errorMessage" class="bio-nexus-message bio-nexus-message-error">{{errorMessage}}</div></section><template #footer><button class="bio-nexus-action bio-nexus-action-secondary" :disabled="saving" @click="close"><BioNexusActionIcon action="cancel"/>Cancelar</button><button class="bio-nexus-action bio-nexus-action-primary" :disabled="submitDisabled" @click="submit"><BioNexusActionIcon action="save"/>{{saving?'Guardando...':mode==='create'?'Crear':'Guardar'}}</button></template></BioNexusDialog></template>
<script setup>import{computed,nextTick,reactive,ref}from'vue';import BioNexusDialog from'@/components/ui/BioNexusDialog.vue';import BioNexusFormField from'@/components/ui/BioNexusFormField.vue';import BioNexusActionIcon from'@/components/ui/BioNexusActionIcon.vue';const props=defineProps({saving:Boolean,canCreate:Boolean,canUpdate:Boolean}),emit=defineEmits(['submit']),dialog=ref(null),firstInput=ref(null),mode=ref('create'),current=ref(null),attempted=ref(false),errorMessage=ref(''),original=ref(''),dirty=ref(false),draft=reactive({code:'',name:'',symbol:'',symbolPosition:'before',decimalPlaces:2});const options=[{code:'VES',name:'Bolívar venezolano',symbol:'Bs.'},{code:'USD',name:'Dólar estadounidense',symbol:'$'},{code:'EUR',name:'Euro',symbol:'€'},{code:'GBP',name:'Libra esterlina',symbol:'£'},{code:'COP',name:'Peso colombiano',symbol:'$'},{code:'BRL',name:'Real brasileño',symbol:'R$'},{code:'MXN',name:'Peso mexicano',symbol:'$'},{code:'ARS',name:'Peso argentino',symbol:'$'},{code:'CLP',name:'Peso chileno',symbol:'$'},{code:'PEN',name:'Sol peruano',symbol:'S/'}],values=computed(()=>({code:String(draft.code||'').trim().toUpperCase(),name:String(draft.name||'').trim(),symbol:String(draft.symbol||'').trim(),symbolPosition:draft.symbolPosition,decimalPlaces:Number(draft.decimalPlaces)})),identity=computed(()=>`${current.value?.name||draft.name} (${current.value?.code||draft.code})`),preview=computed(()=>draft.symbolPosition==='after'?`1.250,00 ${draft.symbol}`:`${draft.symbol} 1.250,00`),errors=computed(()=>attempted.value?{code:/^[A-Z]{3}$/.test(values.value.code)?'':'Selecciona una moneda.',name:values.value.name?'':'Ingresa el nombre de la moneda.',symbol:values.value.symbol?'':'Ingresa el símbolo de la moneda.',decimals:Number.isInteger(values.value.decimalPlaces)&&values.value.decimalPlaces>=0&&values.value.decimalPlaces<=6?'':'Los decimales deben estar entre 0 y 6.'}:{code:'',name:'',symbol:'',decimals:''}),submitDisabled=computed(()=>props.saving||(mode.value==='create'?!props.canCreate:!props.canUpdate||!dirty.value));function signature(){return JSON.stringify(values.value)}function syncDirty(){dirty.value=signature()!==original.value}function assign(row){Object.assign(draft,{code:row?.code||'',name:row?.name||'',symbol:row?.symbol||'',symbolPosition:row?.symbolPosition||'before',decimalPlaces:Number(row?.decimalPlaces??2)})}function selectCurrency(){const item=options.find(x=>x.code===draft.code);if(item){draft.name=item.name;draft.symbol=item.symbol}syncDirty()}async function show(){original.value=signature();dirty.value=false;await dialog.value?.open();await nextTick();original.value=signature();dirty.value=false;firstInput.value?.focus()}async function openCreate(){mode.value='create';current.value=null;assign(null);attempted.value=false;errorMessage.value='';await show()}async function openEdit(row){mode.value='edit';current.value=row;assign(row);attempted.value=false;errorMessage.value='';await show()}function submit(){attempted.value=true;if(Object.values(errors.value).some(Boolean)||submitDisabled.value)return;emit('submit',{mode:mode.value,record:current.value,values:values.value})}function close(){dialog.value?.close()}function reset(){attempted.value=false;dirty.value=false}defineExpose({openCreate,openEdit,close,setError:v=>errorMessage.value=String(v||''),clearError:()=>errorMessage.value=''})</script><style scoped>.currency-form{display:grid;grid-template-columns:1fr 1fr;gap:var(--bio-nexus-space-3);font:400 13px var(--bio-nexus-font-family,Inter,Roboto,Arial,sans-serif)}.readonly{background:var(--bio-nexus-color-surface-soft);cursor:not-allowed}.preview{display:grid;gap:2px;padding:8px 12px;border:1px solid var(--bio-nexus-color-border);border-radius:var(--bio-nexus-radius-sm);background:var(--bio-nexus-color-surface-soft)}.preview span{color:var(--bio-nexus-color-text-muted);font-size:11px}.bio-nexus-message{grid-column:1/-1}@media(max-width:620px){.currency-form{grid-template-columns:1fr}}</style>